import{z as s,x as n,o as B,c as D,q as t,j as r,D as A,d as e,s as o,S as i,b as a}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"对齐数据的评测闭环","description":"","frontmatter":{"title":"对齐数据的评测闭环","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ade-eval-loop.md","filePath":"llm/ade-eval-loop.md","lastUpdated":1791063341000}'),C={name:"llm/ade-eval-loop.md"};function d(p,E,T,m,F,h){const l=n("Mermaid");return B(),D("div",null,[E[2]||(E[2]=t('<h1 id="对齐数据的评测闭环" tabindex="-1">对齐数据的评测闭环 <a class="header-anchor" href="#对齐数据的评测闭环" aria-label="Permalink to &quot;对齐数据的评测闭环&quot;">​</a></h1><div class="epigraph"><p>模型要评测，数据也要：评的不是模型答得好不好，而是这份数据还定义得动边界吗。</p><footer>—— 据 Touvron 等 Llama 2, 2023 的迭代评测与本课程口径整理</footer></div><p><a href="/llm/ade-iteration-data-strategy">上一课</a>把轮次间的采集收在失败驱动与新旧混锚；本课补上闭环的最后一环：数据侧自己的仪表，以及它怎么接上模型评测的门禁。模型侧的评测体系有整门对齐评测深钻，收束在<a href="/llm/aeval-map">对齐评测收束</a>；本课不重讲模型怎么测，只写数据侧的仪表怎么让那些失败可归因。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>团队普遍盯着模型分数，数据指标静默腐烂：标注团队换人，一致率慢慢掉没人看见；轮次滚动，配比被一批批新数据悄悄搬动；持有集与训练池的近邻越来越像，验证读数虚高；政策改版三个月，安全池里一半对子还按旧政策标着。这些都不立刻体现在模型分数上——分数的变化要等下一次训练才显形，显形时已经分不清是数据的问题还是训练的问题。缺口是把数据质量做成有门禁、有触发条件的仪表，并且与模型评测的门禁接成同一个环。</p><p><span class="marginnote">「持有集」就是刻意不拿去训练、专门留着考试的数据；「训练池」则是平时刷题的题库。如果考试的题混进了题库，学生考高分只说明背过答案，不代表会做——所以要有泄漏仪表，用近邻检测把长得太像的题挑出来。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>四类仪表加一个接缝。质量仪表：分批、分团队的一致率与仲裁率，指南版本 diff——掉出门禁就停采，先修标注流程。分布仪表：覆盖矩阵（意图 × 危害类别）逐轮对比，配比漂移报警——移动超阈值触发配比复核。泄漏仪表：持有集对训练池的近邻检测（与去重同一把尺），回归集零训练断言。锚仪表：旧提示重标不一致率，政策版本对齐检查。接缝是归因三分：模型评测的失败落进三个格子——数据没覆盖（采集问题）、覆盖了但标错（噪声问题）、政策改了数据没跟上（版本问题）；三个格子对应三个动作：补采、仲裁重标、政策重映射。混在一起就只剩一个动作——再采一批，恰好是最贵的那一个。</p>',8)),(B(),r(i,null,{default:A(()=>[o(l,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20DQ%5B%22%E8%B4%A8%E9%87%8F%E4%BB%AA%E8%A1%A8%EF%BC%9A%E4%B8%80%E8%87%B4%E7%8E%87%20%2F%20%E4%BB%B2%E8%A3%81%E7%8E%87%22%5D%20--%3E%20ATTR%7B%22%E5%BD%92%E5%9B%A0%E4%B8%89%E5%88%86%22%7D%0A%20%20DD%5B%22%E5%88%86%E5%B8%83%E4%BB%AA%E8%A1%A8%EF%BC%9A%E8%A6%86%E7%9B%96%E7%9F%A9%E9%98%B5%20%2F%20%E9%85%8D%E6%AF%94%E6%BC%82%E7%A7%BB%22%5D%20--%3E%20ATTR%0A%20%20DL%5B%22%E6%B3%84%E6%BC%8F%E4%BB%AA%E8%A1%A8%EF%BC%9A%E8%BF%91%E9%82%BB%20%2F%20%E9%9B%B6%E8%AE%AD%E7%BB%83%E6%96%AD%E8%A8%80%22%5D%20--%3E%20ATTR%0A%20%20DA%5B%22%E9%94%9A%E4%BB%AA%E8%A1%A8%EF%BC%9A%E9%87%8D%E6%A0%87%E4%B8%80%E8%87%B4%E7%8E%87%20%2F%20%E7%89%88%E6%9C%AC%E5%AF%B9%E9%BD%90%22%5D%20--%3E%20ATTR%0A%20%20ATTR%20--%3E%7C%22%E6%B2%A1%E8%A6%86%E7%9B%96%22%7C%20COLLECT%5B%22%E8%A1%A5%E9%87%87%22%5D%0A%20%20ATTR%20--%3E%7C%22%E6%A0%87%E9%94%99%22%7C%20RELABEL%5B%22%E4%BB%B2%E8%A3%81%E9%87%8D%E6%A0%87%22%5D%0A%20%20ATTR%20--%3E%7C%22%E7%89%88%E6%9C%AC%E8%BF%87%E6%9C%9F%22%7C%20REMAP%5B%22%E6%94%BF%E7%AD%96%E9%87%8D%E6%98%A0%E5%B0%84%22%5D%0A%20%20COLLECT%20--%3E%20CARD%5B%22%E6%95%B0%E6%8D%AE%E5%8D%A1%E6%96%B0%E7%89%88%E6%9C%AC%22%5D%0A%20%20RELABEL%20--%3E%20CARD%0A%20%20REMAP%20--%3E%20CARD%0A%20%20CARD%20--%3E%20TRAIN%5B%22%E8%AE%AD%E7%BB%83%22%5D%0A%20%20TRAIN%20--%3E%20GATE%5B%22%E6%A8%A1%E5%9E%8B%E8%AF%84%E6%B5%8B%E9%97%A8%E7%A6%81%22%5D%0A%20%20GATE%20--%3E%7C%22%E5%A4%B1%E8%B4%A5%22%7C%20ATTR%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[e("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"闭环为什么必须闭合：模型门禁只报「哪里失败」，数据仪表报「失败在数据侧的对应物存不存在」——两边的格子一对，归因才有分母。持有一个机制性的细节：验证集是数据的抽样，数据分布一动，验证读数的指称就变了——这就是为什么数据卡版本必须绑进模型检查点（第一课的资产观），否则跨轮比较的两个数字根本不指同一个量。锚仪表的机制在轮次课给过：重标不一致率同时含口径差与随机误差，要配未改版对照组。所有仪表的共同性质是便宜：它们都是对已有数据的统计，不需要新标注——最贵的动作永远是盲目的那一次补采。",-1)),E[5]||(E[5]=a("p",null,"拿到一次模型评测失败后，归因三分的分诊流程是先查覆盖、再查标签、最后查版本，三问走完仍无答案的才移交训练侧排查：",-1)),(B(),r(i,null,{default:A(()=>[o(l,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E6%A8%A1%E5%9E%8B%E8%AF%84%E6%B5%8B%E6%8A%A5%E4%B8%80%E6%AC%A1%E5%A4%B1%E8%B4%A5%22%5D%20--%3E%20Q1%7B%22%E8%A6%86%E7%9B%96%E7%9F%A9%E9%98%B5%E9%87%8C%E6%9C%89%E8%BF%99%E4%B8%AA%E6%84%8F%E5%9B%BE%20%C3%97%20%E5%8D%B1%E5%AE%B3%E6%A0%BC%E5%AD%90%E5%90%97%22%7D%0A%20%20Q1%20--%3E%7C%22%E6%B2%A1%E6%9C%89%22%7C%20A1%5B%22%E9%87%87%E9%9B%86%E9%97%AE%E9%A2%98%20%E2%86%92%20%E8%A1%A5%E9%87%87%22%5D%0A%20%20Q1%20--%3E%7C%22%E6%9C%89%22%7C%20Q2%7B%22%E6%8A%BD%E6%A0%B7%E6%A0%B8%E5%AF%B9%E6%A0%87%E7%AD%BE%E4%B8%8E%E5%BD%93%E5%89%8D%E6%94%BF%E7%AD%96%22%7D%0A%20%20Q2%20--%3E%7C%22%E6%A0%87%E9%94%99%E4%BA%86%22%7C%20A2%5B%22%E5%99%AA%E5%A3%B0%E9%97%AE%E9%A2%98%20%E2%86%92%20%E4%BB%B2%E8%A3%81%E9%87%8D%E6%A0%87%22%5D%0A%20%20Q2%20--%3E%7C%22%E6%A0%87%E7%AD%BE%E6%B2%A1%E9%94%99%22%7C%20Q3%7B%22%E6%95%B0%E6%8D%AE%E6%8C%89%E7%9A%84%E6%98%AF%E6%97%A7%E6%94%BF%E7%AD%96%E7%89%88%E6%9C%AC%E5%90%97%22%7D%0A%20%20Q3%20--%3E%7C%22%E6%98%AF%22%7C%20A3%5B%22%E7%89%88%E6%9C%AC%E9%97%AE%E9%A2%98%20%E2%86%92%20%E6%94%BF%E7%AD%96%E9%87%8D%E6%98%A0%E5%B0%84%22%5D%0A%20%20Q3%20--%3E%7C%22%E5%90%A6%22%7C%20OTHER%5B%22%E5%BD%92%E5%9B%A0%E5%88%B0%E8%AE%AD%E7%BB%83%E4%BE%A7%EF%BC%8C%E6%95%B0%E6%8D%AE%E4%BB%AA%E8%A1%A8%E6%97%A0%E8%B4%A3%22%5D%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=t('<p><span class="marginnote">「一致率」可以这样理解：让两位标注员独立标同一批数据，统计他们给出相同答案的比例。假设抽 200 条、两人有 170 条标得一样，一致率就是 85%。低于门禁说明指南写得含糊或有人没读懂——注意它只测「稳不稳」，测不出「对不对」。</span></p><p><span class="marginnote">上线前最便宜的三个断言：回归集与训练集交集为零；持有集与训练池的最大相似度不超过去重阈值；每个检查点查得到数据卡版本。三条过不了，后面的分数不用看。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>数据仪表不替代模型评测：一致率高只说明流程稳，不说明指南对——锚定错了的指南，一致率越高错得越整齐，外部金标与人审抽检是另一道。仪表也有盲区：标注员的系统性偏差在一致率上不可见（大家一致地偏），要靠评测侧的对照探针兜住。闭环的尽头还是那个前提：判断可成文、可采集；超出成文范围的部分，本课程的仪表都够不着。</p><p><span class="marginnote">「对照探针」像考试里故意混进去的送分题和陷阱题：正确答案早就知道。如果整个流程连送分题都答错，说明存在大家「一致地偏」的系统性偏差，而不是这道题特别难——这正是标注一致率看不见的那类问题。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>数据侧四类仪表：质量（一致率/仲裁率）、分布（覆盖矩阵/配比漂移）、泄漏（近邻/零训练断言）、锚（重标/版本对齐）。</li><li>接缝是归因三分：没覆盖、标错、版本过期对应补采、重标、重映射，别把三个动作混成「再采一批」。</li><li>数据卡版本绑进模型检查点，跨轮的数字才有同一指称。</li><li>一致率高不等于指南对；系统性偏差要在评测侧用对照探针兜住。</li><li>出处：Touvron 等 Llama 2，2023；模型侧门禁体系见对齐评测收束课，按本课程整理。</li></ul>',7))])}const _=s(C,[["render",d]]);export{u as __pageData,_ as default};
